const windowsCiMsixBuildIndex = ciWorkflow.indexOf('Build Windows Release shell for MSIX')
const windowsCiUploadIndex = ciWorkflow.indexOf('name: windows-release-shell')
if (
  windowsCiBuildIndex === -1 ||
  windowsCiSmokeIndex === -1 ||
  windowsCiArtifactCheckIndex === -1 ||
  windowsCiMsixBuildIndex === -1 ||
  windowsCiUploadIndex === -1 ||
  windowsCiSmokeIndex < windowsCiBuildIndex ||
  windowsCiArtifactCheckIndex < windowsCiSmokeIndex ||
  windowsCiMsixBuildIndex < windowsCiArtifactCheckIndex ||
  windowsCiUploadIndex < windowsCiMsixBuildIndex
) {
  failures.push(
    'Windows CI must build unpackaged output, smoke the WebView window, validate artifacts, rebuild MSIX-ready output, then upload.',
  )
}

const appleCiSmokeIndex = ciWorkflow.indexOf('Smoke macOS runtime')
const appleCiArtifactCheckIndex = ciWorkflow.indexOf('Validate Apple runtime smoke artifact')
const appleCiUploadIndex = ciWorkflow.indexOf('name: apple-runtime-smoke')
if (
  appleCiSmokeIndex === -1 ||
  appleCiArtifactCheckIndex === -1 ||
  appleCiUploadIndex === -1 ||
  appleCiArtifactCheckIndex < appleCiSmokeIndex ||
  appleCiUploadIndex < appleCiArtifactCheckIndex
) {
  failures.push(
    'Apple CI must validate runtime smoke artifacts after capture and before upload.',
  )
}

